"""Authored A2 Spanish cues for stable quizzes, independent of model output.

Order follows the verified textbook glossary in a2_sample. These are original
explanations, not quotations. Shared forms keep their category-specific sense.
"""
from .a2_sample import WORDS, GROUPS

