CLUES = {}
for group_index, (category, items) in enumerate(GROUPS.items()):
    clues = CLUE_GROUPS[category].split('|')
    assert len(clues) == len(items.split(';')), category
    CLUES.update({f'{group_index}-{i}': clue for i, clue in enumerate(clues)})

BY_ID = {word['id']: {**word, 'clue': CLUES[word['id']]} for word in WORDS}

# A personal introduction becomes a social encounter, then a learning plan.
ORDER = ['Carácter', 'Intereses', 'Tiempo libre', 'Comida', 'Ropa', 'Animales',
         'Redes sociales', 'Para preguntar', 'En la escuela de español', 'En la ciudad']
TITLES = ['Así soy', 'Lo que me interesa', 'Mis ratos libres', 'A la mesa',
          'Mi estilo', 'Animales y personalidad', 'Conocer gente', 'Pedir ayuda',
          'Aprender juntos', 'Explorar la ciudad']
CHAPTERS = []
for category, title in zip(ORDER, TITLES):
    ids = [word['id'] for word in WORDS if word['category'] == category]
    for start in range(0, len(ids), 5):
        CHAPTERS.append({'title': title, 'category': category, 'words': ids[start:start + 5]})
